<a href="/salary"><?= e(t('← Money')) ?></a><header class="page-header asset-heading"><div><p class="eyebrow"><?= e(t('KEEP COMMITMENTS IN VIEW')) ?></p><h1><?= e(t('Your financial calendar.')) ?></h1><p class="muted"><?= e(t('See upcoming bills and loan repayments, then record each payment once.')) ?></p></div></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="tabs" aria-label="<?= e(t('Money pages')) ?>"><a href="/salary"><?= e(t('Transactions')) ?></a><a href="/salary/plan"><?= e(t('Salary plan')) ?></a><a class="selected" href="/salary/calendar"><?= e(t('Financial calendar')) ?></a><a href="/salary/recurring"><?= e(t('Recurring')) ?></a></nav>
<div class="stats"><section class="card"><p class="muted"><?= e(t('Spent today')) ?></p><div class="big-number"><?= money($totals['today']) ?></div></section><section class="card"><p class="muted"><?= e(t('Spent this week')) ?></p><div class="big-number"><?= money($totals['week']) ?></div><small><?= e(t('Since')) ?> <?= e($totals['week_start']) ?></small></section><section class="card"><p class="muted"><?= e(t('Active commitments due within a year')) ?></p><div class="big-number"><?= count($due) ?></div><small><?= e(t('Includes overdue commitments')) ?></small></section></div>
<section class="card"><div class="section-heading"><h2><?= e(t('Due dates')) ?></h2><a href="#add-commitment"><?= e(t('+ Add a bill or loan')) ?></a></div><?php if (!$due): ?><div class="empty"><h3><?= e(t('No financial reminders yet.')) ?></h3><p><?= e(t('Add your bills and loans below. Reminders do not create expenses until you mark them paid.')) ?></p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Due date')) ?></th><th><?= e(t('Commitment')) ?></th><th><?= e(t('Amount / balance')) ?></th><th><?= e(t('Pay from')) ?></th><th><?= e(t('Payment')) ?></th></tr></thead><tbody><?php foreach ($due as $row): ?><tr><td class="<?= $row['due_date']<ui_date('Y-m-d') ? 'error-text' : '' ?>"><?= e($row['due_date']) ?><?= $row['due_date']<ui_date('Y-m-d') ? ' · Overdue' : '' ?></td><td><strong><?= e($row['title']) ?></strong><small><?= e(ucfirst($row['kind'])) ?> · <?= $row['interval']==='monthly' ? t('Monthly') : t('Once') ?></small></td><td><?= money($row['kind']==='loan' ? min($row['amount'],$row['outstanding']) : $row['amount']) ?><?php if ($row['kind']==='loan'): ?><small><?= money($row['outstanding']) ?> <?= e(t('outstanding')) ?></small><?php endif; ?></td><td><?= e($row['account']) ?><small><?= e($row['category']) ?></small></td><td><form class="stack" method="post" action="/salary/obligations/<?= e($row['id']) ?>/pay"><?= csrf_field() ?><input type="hidden" name="due_date" value="<?= e($row['due_date']) ?>"><label><?= e(t('Paid on')) ?><input type="date" name="paid_date" value="<?= e(ui_date('Y-m-d')) ?>" required></label><button><?= e(t('Mark paid')) ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="card" id="add-commitment"><h2><?= e(t('Add a bill or loan')) ?></h2><form class="form-grid" method="post" action="/salary/obligations"><?= csrf_field() ?><label><?= e(t('Title')) ?><input name="title" maxlength="150" required></label><label><?= e(t('Type')) ?><select name="kind"><option value="bill"><?= e(t('Bill')) ?></option><option value="loan"><?= e(t('Loan payment')) ?></option></select></label><label><?= e(t('Payment amount (LKR)')) ?><input name="amount" type="number" min="0.01" max="9999999999.99" step="0.01" required></label><label><?= e(t('First due date')) ?><input name="due_date" type="date" required></label><label><?= e(t('Schedule')) ?><select name="interval"><option value="none"><?= e(t('Once')) ?></option><option value="monthly"><?= e(t('Monthly')) ?></option></select></label><label><?= e(t('Loan outstanding balance (loans only)')) ?><input name="outstanding" type="number" min="0.01" max="9999999999.99" step="0.01"></label><label><?= e(t('Payment account')) ?><select name="account_id"><?php foreach ($accounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Expense category')) ?><select name="category_id"><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><div class="full"><button><?= e(t('Add financial reminder')) ?></button></div></form><p class="footnote"><?= e(t('Monthly schedules preserve the original due-day: a reminder for the 31st moves to February’s last day, then back to the 31st where possible. Loans record the smaller of the payment amount and outstanding balance. Choose monthly for loans needing multiple payments.')) ?></p></section>
<?php if ($obligations): ?><section class="card"><h2><?= e(t('All commitments')) ?></h2><div class="table-wrap"><table><thead><tr><th><?= e(t('Commitment')) ?></th><th><?= e(t('Next due')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Action')) ?></th></tr></thead><tbody><?php foreach ($obligations as $row): ?><tr><td><?= e($row['title']) ?><small><?= e(ucfirst($row['kind'])) ?><?= $row['kind']==='loan' ? ' · '.money($row['outstanding']).' outstanding' : '' ?></small></td><td><?= e($row['due_date']) ?></td><td><?= $row['active'] ? t('Active') : ($row['kind']==='loan' && $row['outstanding']<=0 ? t('Repaid') : t('Paused / completed')) ?></td><td><?php if ($row['kind']!=='loan' || $row['outstanding']>0): ?><form method="post" action="/salary/obligations/<?= e($row['id']) ?>/status"><?= csrf_field() ?><input type="hidden" name="active" value="<?= $row['active'] ? '0' : '1' ?>"><button class="secondary"><?= $row['active'] ? t('Pause') : t('Activate') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="card"><h2><?= e(t('Payment history')) ?></h2><?php if (!$payments): ?><p class="muted"><?= e(t('No payments recorded yet.')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Commitment')) ?></th><th><?= e(t('Due / paid')) ?></th><th><?= e(t('Amount')) ?></th><th><?= e(t('Status')) ?></th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= e($payment['title']) ?></td><td><?= e($payment['due_date']) ?><small><?= e(t('Paid')) ?> <?= e($payment['paid_date']) ?></small></td><td><?= money($payment['amount']) ?></td><td><?= e(ucfirst($payment['status'])) ?><?= $payment['expense_id'] ? ' · Expense #'.e($payment['expense_id']) : '' ?></td></tr><?php endforeach; ?></tbody></table></div><p class="footnote"><?= e(t('To reverse a payment, delete its matching expense from Money. The account balance and loan outstanding balance are restored, and the payment becomes due again.')) ?></p><?php endif; ?></section>
